import React, { useState } from 'react';
import { rdsn } from '@/api/supabaseClient';
import { useQuery } from '@tanstack/react-query';
import { AlertTriangle, Trash2, Loader, Filter, X } from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";

export default function LimparDadosProducao() {
  const [showDialog, setShowDialog] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [resultados, setResultados] = useState(null);
  const [modoExclusao, setModoExclusao] = useState('total');
  const [filtros, setFiltros] = useState({
    codigos: [],
    clientes: [],
    modelos: [],
    numero_inicial: '',
    numero_final: ''
  });
  const [inputValues, setInputValues] = useState({
    codigo: '',
    cliente: '',
    modelo: ''
  });

  // Buscar dados para os filtros
  const { data: reservas = [] } = useQuery({
    queryKey: ['reservas-filtros'],
    queryFn: () => rdsn.entities.ReservaLote.list()
  });

  const { data: clientes = [] } = useQuery({
    queryKey: ['clientes-filtros'],
    queryFn: () => rdsn.entities.Cliente.list()
  });

  // Extrair opções únicas
  const codigosDisponiveis = [...new Set(reservas.map(r => r.codigo_produto).filter(Boolean))];
  const clientesDisponiveis = [...new Set([
    ...clientes.map(c => c.nome),
    ...reservas.map(r => r.cliente)
  ].filter(Boolean))];
  const modelosDisponiveis = [...new Set(reservas.map(r => r.modelo).filter(Boolean))];

  const addFiltro = (tipo, valor) => {
    if (!valor.trim()) return;

    const normalizado = valor.trim();
    if (filtros[tipo].includes(normalizado)) {
      toast.error('Este valor já foi adicionado');
      return;
    }

    setFiltros({
      ...filtros,
      [tipo]: [...filtros[tipo], normalizado]
    });
    setInputValues({ ...inputValues, [tipo.replace('s', '')]: '' });
  };

  const removeFiltro = (tipo, valor) => {
    setFiltros({
      ...filtros,
      [tipo]: filtros[tipo].filter(v => v !== valor)
    });
  };

  const handleKeyPress = (e, tipo) => {
    if (e.key === 'Enter') {
      const campo = tipo.replace('s', '');
      addFiltro(tipo, inputValues[campo]);
    }
  };

  const handleLimpar = async () => {
    setIsDeleting(true);
    try {
      // Incluir ID do usuário interno para validação de permissão no backend
      let internalUserId = null;
      try {
        const data = localStorage.getItem('internalUser');
        if (data) {
          const parsed = JSON.parse(data);
          const user = (parsed && parsed.user) ? parsed.user : parsed;
          internalUserId = user.id;
        }
      } catch {}

      const payload = modoExclusao === 'total'
        ? { internalUserId }
        : { filtros, internalUserId };
      const response = await rdsn.functions.invoke('limparDadosProducao', payload);

      if (response.data.success) {
        setResultados(response.data.resultados);
        toast.success(response.data.mensagem);
        setShowDialog(false);

        setTimeout(() => window.location.reload(), 1000);
      }
    } catch (err) {
      toast.error('Erro: ' + err.message);
    } finally {
      setIsDeleting(false);
    }
  };

  const temFiltrosAtivos = filtros.codigos.length > 0 || 
    filtros.clientes.length > 0 || 
    filtros.modelos.length > 0 || 
    filtros.numero_inicial || 
    filtros.numero_final;

  return (
    <>
      <Card className="border-red-200 bg-red-50">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-red-700">
            <AlertTriangle className="w-5 h-5" />
            Limpeza de Dados de Produção
          </CardTitle>
          <CardDescription>
            Remova registros de produção do sistema
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Tabs value={modoExclusao} onValueChange={setModoExclusao} className="mb-4">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="total">Exclusão Total</TabsTrigger>
              <TabsTrigger value="seletiva">Exclusão Seletiva</TabsTrigger>
            </TabsList>

            <TabsContent value="total" className="space-y-4">
              <Alert variant="destructive">
                <AlertTriangle className="h-4 w-4" />
                <AlertDescription>
                  Esta ação é irreversível! Serão deletados TODOS os registros: reservas, baixas, sequências, numerações livres, bloqueios, notificações, alertas, movimentações de estoque, auditorias, tarefas, relatórios e KPIs.
                </AlertDescription>
              </Alert>

              <Button
                variant="destructive"
                onClick={() => setShowDialog(true)}
                className="gap-2"
              >
                <Trash2 className="w-4 h-4" />
                Limpar Todos os Dados
              </Button>
            </TabsContent>

            <TabsContent value="seletiva" className="space-y-4">
              <Alert>
                <Filter className="h-4 w-4" />
                <AlertDescription>
                  Defina filtros para deletar apenas registros específicos. Deixe em branco para não filtrar.
                </AlertDescription>
              </Alert>

              <div className="space-y-4">
                {/* Código do Produto */}
                <div className="space-y-2">
                  <Label>Código do Produto (múltipla escolha)</Label>
                  <div className="flex gap-2">
                    <Input
                      placeholder="Digite e pressione Enter"
                      value={inputValues.codigo}
                      onChange={(e) => setInputValues({...inputValues, codigo: e.target.value})}
                      onKeyPress={(e) => handleKeyPress(e, 'codigos')}
                      list="codigos-list"
                    />
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => addFiltro('codigos', inputValues.codigo)}
                    >
                      Adicionar
                    </Button>
                  </div>
                  <datalist id="codigos-list">
                    {codigosDisponiveis.map(cod => (
                      <option key={cod} value={cod} />
                    ))}
                  </datalist>
                  {filtros.codigos.length > 0 && (
                    <div className="flex flex-wrap gap-2 mt-2">
                      {filtros.codigos.map(cod => (
                        <Badge key={cod} variant="secondary" className="gap-1">
                          {cod}
                          <X 
                            className="w-3 h-3 cursor-pointer" 
                            onClick={() => removeFiltro('codigos', cod)}
                          />
                        </Badge>
                      ))}
                    </div>
                  )}
                </div>

                {/* Cliente */}
                <div className="space-y-2">
                  <Label>Cliente (múltipla escolha)</Label>
                  <div className="flex gap-2">
                    <Input
                      placeholder="Digite e pressione Enter"
                      value={inputValues.cliente}
                      onChange={(e) => setInputValues({...inputValues, cliente: e.target.value})}
                      onKeyPress={(e) => handleKeyPress(e, 'clientes')}
                      list="clientes-list"
                    />
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => addFiltro('clientes', inputValues.cliente)}
                    >
                      Adicionar
                    </Button>
                  </div>
                  <datalist id="clientes-list">
                    {clientesDisponiveis.map(cli => (
                      <option key={cli} value={cli} />
                    ))}
                  </datalist>
                  {filtros.clientes.length > 0 && (
                    <div className="flex flex-wrap gap-2 mt-2">
                      {filtros.clientes.map(cli => (
                        <Badge key={cli} variant="secondary" className="gap-1">
                          {cli}
                          <X 
                            className="w-3 h-3 cursor-pointer" 
                            onClick={() => removeFiltro('clientes', cli)}
                          />
                        </Badge>
                      ))}
                    </div>
                  )}
                </div>

                {/* Modelo */}
                <div className="space-y-2">
                  <Label>Modelo (múltipla escolha)</Label>
                  <div className="flex gap-2">
                    <Input
                      placeholder="Digite e pressione Enter"
                      value={inputValues.modelo}
                      onChange={(e) => setInputValues({...inputValues, modelo: e.target.value})}
                      onKeyPress={(e) => handleKeyPress(e, 'modelos')}
                      list="modelos-list"
                    />
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => addFiltro('modelos', inputValues.modelo)}
                    >
                      Adicionar
                    </Button>
                  </div>
                  <datalist id="modelos-list">
                    {modelosDisponiveis.map(mod => (
                      <option key={mod} value={mod} />
                    ))}
                  </datalist>
                  {filtros.modelos.length > 0 && (
                    <div className="flex flex-wrap gap-2 mt-2">
                      {filtros.modelos.map(mod => (
                        <Badge key={mod} variant="secondary" className="gap-1">
                          {mod}
                          <X 
                            className="w-3 h-3 cursor-pointer" 
                            onClick={() => removeFiltro('modelos', mod)}
                          />
                        </Badge>
                      ))}
                    </div>
                  )}
                </div>

                {/* Numeração */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>Numeração Inicial</Label>
                    <Input
                      type="number"
                      placeholder="Ex: 1000"
                      value={filtros.numero_inicial}
                      onChange={(e) => setFiltros({...filtros, numero_inicial: e.target.value})}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label>Numeração Final</Label>
                    <Input
                      type="number"
                      placeholder="Ex: 2000"
                      value={filtros.numero_final}
                      onChange={(e) => setFiltros({...filtros, numero_final: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <Alert variant="destructive">
                <AlertTriangle className="h-4 w-4" />
                <AlertDescription>
                  Registros que corresponderem aos filtros serão deletados permanentemente!
                </AlertDescription>
              </Alert>

              <Button
                variant="destructive"
                onClick={() => setShowDialog(true)}
                className="gap-2"
                disabled={!temFiltrosAtivos}
              >
                <Trash2 className="w-4 h-4" />
                Limpar Dados Filtrados
              </Button>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>

      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="text-red-700 flex items-center gap-2">
              <AlertTriangle className="w-5 h-5" />
              Confirmar Limpeza
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-3">
            {modoExclusao === 'total' ? (
              <>
                <p className="text-sm text-slate-700">
                  Você tem certeza que deseja deletar TODOS os dados de produção?
                </p>
                <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-xs text-red-700 space-y-1">
                  <p><strong>Será deletado TODO E QUALQUER registro:</strong></p>
                  <ul className="list-disc list-inside space-y-1">
                    <li>Todas as reservas de lotes</li>
                    <li>Todos os registros de baixa</li>
                    <li>Todas as sequências anuais</li>
                    <li>Todas as numerações livres</li>
                    <li>Todos os bloqueios de intervalo</li>
                    <li>Todas as notificações</li>
                    <li>Todos os alertas</li>
                    <li>Todas as movimentações de estoque</li>
                    <li>Todas as auditorias de produção</li>
                    <li>Todas as auditorias de usuários</li>
                    <li>Todas as tarefas agendadas</li>
                    <li>Todos os relatórios customizados</li>
                    <li>Todas as configurações de KPI</li>
                  </ul>
                </div>
                <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-3">
                  <p className="text-xs text-emerald-800 font-bold">
                    ✅ PRESERVADOS: Produtos, Clientes, Setores e Usuários
                  </p>
                  <p className="text-xs text-emerald-700 mt-1">
                    Estes dados cadastrais são mantidos e não serão deletados
                  </p>
                </div>
              </>
            ) : (
              <>
                <p className="text-sm text-slate-700">
                  Você tem certeza que deseja deletar os dados que correspondem aos filtros?
                </p>
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-xs text-blue-700 space-y-1">
                  <p><strong>Filtros aplicados:</strong></p>
                  <ul className="space-y-1">
                    {filtros.codigos.length > 0 && (
                      <li>• Códigos: <strong>{filtros.codigos.join(', ')}</strong></li>
                    )}
                    {filtros.clientes.length > 0 && (
                      <li>• Clientes: <strong>{filtros.clientes.join(', ')}</strong></li>
                    )}
                    {filtros.modelos.length > 0 && (
                      <li>• Modelos: <strong>{filtros.modelos.join(', ')}</strong></li>
                    )}
                    {filtros.numero_inicial && <li>• Numeração inicial: <strong>{filtros.numero_inicial}</strong></li>}
                    {filtros.numero_final && <li>• Numeração final: <strong>{filtros.numero_final}</strong></li>}
                  </ul>
                </div>
                <Alert variant="destructive">
                  <AlertTriangle className="h-4 w-4" />
                  <AlertDescription className="text-xs">
                    Serão deletadas reservas, baixas e dados relacionados que corresponderem a estes critérios!
                  </AlertDescription>
                </Alert>
              </>
            )}
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowDialog(false)}
              disabled={isDeleting}
            >
              Cancelar
            </Button>
            <Button
              variant="destructive"
              onClick={handleLimpar}
              disabled={isDeleting}
              className="gap-2"
            >
              {isDeleting ? (
                <>
                  <Loader className="w-4 h-4 animate-spin" />
                  Limpando...
                </>
              ) : (
                <>
                  <Trash2 className="w-4 h-4" />
                  Confirmar Limpeza
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React, { useState } from 'react';
import { rdsn } from '@/api/supabaseClient';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { RotateCcw, Loader2, Upload, CheckCircle, AlertTriangle } from 'lucide-react';
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

export default function RestaurarBackup({ backups = [] }) {
  const queryClient = useQueryClient();
  const [dialogAberto, setDialogAberto] = useState(false);
  const [backupSelecionado, setBackupSelecionado] = useState(null);
  const [previewDados, setPreviewDados] = useState(null);
  const [carregandoPreview, setCarregandoPreview] = useState(false);

  const restaurarMutation = useMutation({
    mutationFn: (arquivo_url) => rdsn.functions.invoke('restaurarBackup', { arquivo_url }),
    onSuccess: (response) => {
      toast.success(response.data.mensagem);
      queryClient.invalidateQueries();
      setDialogAberto(false);
      setPreviewDados(null);
      setBackupSelecionado(null);
    },
    onError: (error) => {
      toast.error('Erro ao restaurar: ' + (error.response?.data?.error || error.message));
    }
  });

  const carregarPreview = async (url) => {
    setCarregandoPreview(true);
    try {
      const response = await fetch(url);
      const data = await response.json();
      setPreviewDados(data);
    } catch (err) {
      toast.error('Erro ao carregar preview do backup');
    }
    setCarregandoPreview(false);
  };

  const handleSelecionarBackup = async (backup) => {
    setBackupSelecionado(backup);
    setDialogAberto(true);
    await carregarPreview(backup.arquivo_url);
  };

  const handleUploadArquivo = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    try {
      const { file_url } = await rdsn.integrations.Core.UploadFile({ file });
      setBackupSelecionado({ arquivo_url: file_url, tipo: 'UPLOAD' });
      setDialogAberto(true);
      await carregarPreview(file_url);
    } catch (err) {
      toast.error('Erro ao fazer upload: ' + err.message);
    }
  };

  const handleRestaurar = () => {
    if (!backupSelecionado?.arquivo_url) return;
    restaurarMutation.mutate(backupSelecionado.arquivo_url);
  };

  const entidadesTransacionais = ['reservas', 'baixas', 'sequencias', 'numeracoes', 'bloqueios',
    'movimentacoes', 'auditorias', 'alertas', 'notificacoes', 'producao_dia', 'producao_dia_lotes'];

  return (
    <>
      <Card className="border-blue-200 dark:border-blue-500/20 bg-blue-50/30 dark:bg-blue-500/5 backdrop-blur-xl rounded-[2rem] overflow-hidden shadow-xl">
        <CardHeader className="border-b border-blue-100 dark:border-blue-500/10 pb-4">
          <CardTitle className="flex items-center gap-3 text-blue-800 dark:text-blue-400 font-black uppercase tracking-tighter italic">
            <span className="w-10 h-10 rounded-2xl bg-blue-500/10 flex items-center justify-center">
              <RotateCcw className="w-5 h-5" />
            </span>
            Restaurar Backup
          </CardTitle>
          <CardDescription className="dark:text-blue-300/60 font-medium">
            Restaure dados transacionais a partir de um backup existente ou arquivo JSON
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6 pt-6">
          {backups.filter(b => b.status === 'SUCESSO' && b.arquivo_url).length > 0 ? (
            <div className="space-y-3">
              <p className="text-[10px] font-black uppercase tracking-widest text-blue-600 dark:text-blue-400 ml-1">Snapshots Disponíveis:</p>
              {backups.filter(b => b.status === 'SUCESSO' && b.arquivo_url).slice(0, 5).map((backup) => (
                <div
                  key={backup.id}
                  className="flex items-center justify-between p-4 rounded-2xl border border-blue-200 dark:border-blue-500/20 bg-white/60 dark:bg-blue-950/40 hover:bg-blue-50 dark:hover:bg-blue-900/40 transition-colors group"
                >
                  <div className="flex gap-4 items-center">
                    <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-blue-500/10 flex items-center justify-center text-blue-600 dark:text-blue-400 group-hover:scale-110 transition-transform">
                      <CheckCircle className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="text-sm font-black text-slate-800 dark:text-slate-100 italic">
                        {new Date(backup.data_backup || backup.created_at).toLocaleString('pt-BR')}
                      </p>
                      <p className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest leading-none mt-0.5">
                        {backup.total_registros?.toLocaleString()} registros • {backup.tipo}
                      </p>
                    </div>
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => handleSelecionarBackup(backup)}
                    className="h-10 rounded-xl border-blue-300 dark:border-blue-500/30 text-blue-700 dark:text-blue-400 hover:bg-blue-100 dark:hover:bg-blue-900/60 font-black uppercase text-[10px] tracking-widest px-4 shadow-sm"
                  >
                    <RotateCcw className="w-3.5 h-3.5 mr-2" />
                    Restaurar
                  </Button>
                </div>
              ))}
            </div>
          ) : (
            <Alert className="bg-amber-50/50 dark:bg-amber-500/5 border-amber-200 dark:border-amber-500/20 rounded-2xl">
              <AlertTriangle className="h-4 w-4 text-amber-600" />
              <AlertDescription className="text-[10px] font-bold uppercase tracking-widest text-amber-700 dark:text-amber-400 italic">
                Nenhum backup disponível no histórico automatizado.
              </AlertDescription>
            </Alert>
          )}

          <div className="border-t border-blue-100 dark:border-blue-500/10 pt-6">
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-3 ml-1">Upload de Manuscrito:</p>
            <label className="flex flex-col items-center justify-center gap-2 p-8 border-2 border-dashed border-blue-200 dark:border-blue-500/20 rounded-[1.5rem] cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-500/5 transition-all group">
              <div className="w-12 h-12 rounded-full bg-blue-100 dark:bg-blue-500/10 flex items-center justify-center text-blue-600 dark:text-blue-400 group-hover:scale-110 transition-transform">
                <Upload className="w-6 h-6" />
              </div>
              <span className="text-xs font-black uppercase tracking-widest text-blue-700 dark:text-blue-400">Importar arquivo JSON externo</span>
              <p className="text-[9px] font-bold text-slate-400 italic">Formatos aceitos: *.json</p>
              <input
                type="file"
                accept=".json"
                className="hidden"
                onChange={handleUploadArquivo}
              />
            </label>
          </div>
        </CardContent>
      </Card>

      <Dialog open={dialogAberto} onOpenChange={setDialogAberto}>
        <DialogContent className="sm:max-w-lg dark:bg-slate-900 dark:border-white/10 rounded-[2rem]">
          <DialogHeader className="mb-4">
            <DialogTitle className="flex items-center gap-3">
              <span className="w-10 h-10 rounded-2xl bg-blue-500/10 flex items-center justify-center">
                <RotateCcw className="w-5 h-5 text-blue-600 dark:text-blue-400" />
              </span>
              Confirmar Restauração
            </DialogTitle>
            <DialogDescription className="font-medium">
              A restauração irá mesclar os dados do backup ao banco de dados atual.
            </DialogDescription>
          </DialogHeader>

          {carregandoPreview ? (
            <div className="flex flex-col items-center justify-center py-12">
              <Loader2 className="w-10 h-10 animate-spin text-blue-600 mb-3" />
              <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 italic">Analisando Estrutura...</p>
            </div>
          ) : previewDados ? (
            <div className="space-y-4">
              <div className="bg-slate-50 dark:bg-slate-950/40 rounded-2xl p-4 border dark:border-white/5">
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1.5 italic">Origem do Snapshot</p>
                <p className="text-sm font-black text-slate-900 dark:text-white italic leading-none">
                  {new Date(previewDados.data_backup).toLocaleString('pt-BR')}
                </p>
                <div className="flex items-center gap-2 mt-2">
                  <div className="px-2 py-0.5 rounded-full bg-slate-200 dark:bg-white/5 text-[8px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-400">VERSÃO {previewDados.versao}</div>
                </div>
              </div>

              <div className="bg-blue-50/50 dark:bg-blue-500/5 rounded-2xl p-5 border border-blue-100 dark:border-blue-500/20">
                <p className="text-[10px] font-black uppercase tracking-widest text-blue-700 dark:text-blue-400 mb-3 ml-1 italic leading-none">Dicionário de dados detectado:</p>
                <div className="grid grid-cols-2 gap-2">
                  {entidadesTransacionais.map(key => {
                    const dados = previewDados.dados?.[key];
                    const count = Array.isArray(dados) ? dados.length : 0;
                    if (count === 0) return null;
                    return (
                      <div key={key} className="flex items-center gap-2 p-2 bg-white dark:bg-slate-900/50 rounded-xl border border-blue-100 dark:border-blue-500/10 shadow-sm">
                        <CheckCircle className="w-3 h-3 text-emerald-500 shrink-0" />
                        <span className="text-[9px] font-bold text-slate-600 dark:text-slate-300 uppercase truncate">
                          {key}: <strong className="text-blue-600 dark:text-blue-400">{count}</strong>
                        </span>
                      </div>
                    );
                  })}
                </div>
              </div>

              <Alert className="bg-amber-500/10 border-amber-500/20 rounded-2xl">
                <AlertTriangle className="h-4 w-4 text-amber-500" />
                <AlertDescription className="text-amber-900 dark:text-amber-400 text-[10px] font-black uppercase tracking-widest italic ml-1 leading-relaxed">
                  Os dados NÃO serão substituídos. Os registros do backup serão anexados à base existente (Upsert).
                </AlertDescription>
              </Alert>
            </div>
          ) : null}

          <DialogFooter className="mt-8 gap-3">
            <Button variant="outline" onClick={() => setDialogAberto(false)} className="rounded-xl h-12 font-bold uppercase text-[10px] tracking-widest px-6">
              Cancelar
            </Button>
            <Button
              onClick={handleRestaurar}
              disabled={restaurarMutation.isPending || !previewDados}
              className="bg-blue-600 hover:bg-blue-700 text-white rounded-xl h-12 font-black uppercase text-[10px] tracking-widest px-8 shadow-xl shadow-blue-600/20"
            >
              {restaurarMutation.isPending ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Injetando Dados...
                </>
              ) : (
                <>
                  <RotateCcw className="w-4 h-4 mr-2" />
                  Confirmar Restauração
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React, { useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Factory, Package } from 'lucide-react';
import { format, startOfWeek, startOfMonth, endOfMonth, addDays, isWithinInterval, isSameDay } from 'date-fns';
import { ptBR } from 'date-fns/locale';

export default function PeriodAnalysis({ reservas, produtos, todasReservas }) {
  const [periodType, setPeriodType] = useState('weekly');
  const [selectedStatus, setSelectedStatus] = useState('all');
  const [selectedCell, setSelectedCell] = useState('all');

  const getCellasUnicas = () => {
    const celulas = new Set();
    produtos.forEach(p => {
      if (p.celulas_permitidas) {
        p.celulas_permitidas.forEach(c => celulas.add(c));
      }
    });
    return Array.from(celulas);
  };

  const getStatusOptions = () => {
    return ['RESERVADO', 'EM_PRODUCAO', 'PRODUZIDO', 'CANCELADO', 'LIBERADO'];
  };

  const filterReservas = (res) => {
    let filtered = res;

    if (selectedStatus !== 'all') {
      filtered = filtered.filter(r => r.status === selectedStatus);
    }

    if (selectedCell !== 'all') {
      filtered = filtered.filter(r => {
        const produto = produtos.find(p => p.letra_produto === r.letra_produto);
        return produto?.celulas_permitidas?.includes(selectedCell);
      });
    }

    return filtered;
  };

  const getPeriodData = useMemo(() => {
    const today = new Date();
    const filtered = filterReservas(todasReservas);
    const periods = [];

    if (periodType === 'daily') {
      for (let i = 0; i < 30; i++) {
        const date = addDays(today, i);
        const dayReservas = filtered.filter(r => 
          r.data_prevista && isSameDay(new Date(r.data_prevista), date)
        );

        periods.push({
          label: format(date, 'EEE dd/MM', { locale: ptBR }),
          date: format(date, 'yyyy-MM-dd'),
          reservas: dayReservas,
          totalUnidades: dayReservas.reduce((sum, r) => sum + (r.quantidade - (r.quantidade_baixada || 0)), 0),
          reservasCount: dayReservas.length
        });
      }
    } else if (periodType === 'weekly') {
      for (let i = 0; i < 12; i++) {
        const weekStart = addDays(startOfWeek(today, { locale: ptBR }), i * 7);
        const weekEnd = addDays(weekStart, 6);

        const weekReservas = filtered.filter(r => 
          r.data_prevista && isWithinInterval(new Date(r.data_prevista), { 
            start: weekStart, 
            end: weekEnd 
          })
        );

        periods.push({
          label: `${format(weekStart, 'dd MMM', { locale: ptBR })} - ${format(weekEnd, 'dd MMM', { locale: ptBR })}`,
          date: format(weekStart, 'yyyy-MM-dd'),
          reservas: weekReservas,
          totalUnidades: weekReservas.reduce((sum, r) => sum + (r.quantidade - (r.quantidade_baixada || 0)), 0),
          reservasCount: weekReservas.length
        });
      }
    } else if (periodType === 'monthly') {
      for (let i = 0; i < 12; i++) {
        const monthStart = startOfMonth(addDays(today, i * 30));
        const monthEnd = endOfMonth(monthStart);

        const monthReservas = filtered.filter(r => 
          r.data_prevista && isWithinInterval(new Date(r.data_prevista), { 
            start: monthStart, 
            end: monthEnd 
          })
        );

        periods.push({
          label: format(monthStart, 'MMMM yyyy', { locale: ptBR }),
          date: format(monthStart, 'yyyy-MM-dd'),
          reservas: monthReservas,
          totalUnidades: monthReservas.reduce((sum, r) => sum + (r.quantidade - (r.quantidade_baixada || 0)), 0),
          reservasCount: monthReservas.length
        });
      }
    }

    return periods.filter(p => p.reservasCount > 0);
  }, [periodType, selectedStatus, selectedCell, todasReservas, filterReservas]);

  const getCargaPeriodo = (periodo) => {
    const capacidadeEstimada = 10000;
    const percentual = (periodo.totalUnidades / capacidadeEstimada) * 100;
    return Math.min(percentual, 100);
  };

  const getCargaCor = (percentual) => {
    if (percentual > 80) return 'bg-red-500';
    if (percentual > 50) return 'bg-amber-500';
    return 'bg-emerald-500';
  };

  const getCargaStatus = (percentual) => {
    if (percentual > 80) return 'Sobrecarga';
    if (percentual > 50) return 'Normal';
    return 'Subutilizado';
  };

  return (
    <div className="space-y-6">
      {/* Filtros */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-2 block">Período</label>
          <Select value={periodType} onValueChange={setPeriodType}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="daily">Diário</SelectItem>
              <SelectItem value="weekly">Semanal</SelectItem>
              <SelectItem value="monthly">Mensal</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div>
          <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-2 block">Status</label>
          <Select value={selectedStatus} onValueChange={setSelectedStatus}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos os Status</SelectItem>
              {getStatusOptions().map(status => (
                <SelectItem key={status} value={status}>{status}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div>
          <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-2 block">Célula de Produção</label>
          <Select value={selectedCell} onValueChange={setSelectedCell}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todas as Células</SelectItem>
              {getCellasUnicas().map(celula => (
                <SelectItem key={celula} value={celula}>{celula}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Períodos */}
      <div className="space-y-3">
        {getPeriodData.length === 0 ? (
          <Card className="border-slate-200 dark:border-white/5 bg-white dark:bg-slate-900/40 backdrop-blur-xl shadow-sm">
            <CardContent className="p-8 text-center text-slate-500 dark:text-slate-400">
              <div className="w-14 h-14 rounded-2xl bg-slate-100 dark:bg-white/5 border border-slate-200/50 dark:border-white/5 flex items-center justify-center mx-auto mb-4">
                <Package className="w-6 h-6 text-slate-400 dark:text-slate-500" />
              </div>
              <p className="text-xs font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Nenhuma reserva encontrada com os filtros selecionados</p>
            </CardContent>
          </Card>
        ) : (
          getPeriodData.map((periodo, idx) => {
            const cargaPerc = getCargaPeriodo(periodo);
            const statusCarga = getCargaStatus(cargaPerc);
            const corCarga = getCargaCor(cargaPerc);

            return (
              <Card key={idx} className="overflow-hidden hover:shadow-md transition-shadow border-slate-200 dark:border-white/5 bg-white dark:bg-slate-900/40 backdrop-blur-xl">
                <CardHeader className="pb-3 bg-slate-50 dark:bg-white/5">
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-base font-semibold text-slate-900 dark:text-white">
                      {periodo.label}
                    </CardTitle>
                    <Badge variant="outline" className="dark:border-white/10 dark:text-slate-300">{periodo.reservasCount} reservas</Badge>
                  </div>
                </CardHeader>

                <CardContent className="pt-4 space-y-4">
                  {/* Unidades e Carga */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900/30 rounded-lg flex items-center justify-center">
                        <Package className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                      </div>
                      <div>
                        <p className="text-xs text-slate-500 dark:text-slate-400">Total de Unidades</p>
                        <p className="text-2xl font-bold text-slate-900 dark:text-white">
                          {periodo.totalUnidades.toLocaleString()}
                        </p>
                      </div>
                    </div>

                    <div className="space-y-2">
                      <p className="text-xs text-slate-500 dark:text-slate-400">Carga do Período</p>
                      <div className="flex items-center gap-3">
                        <div className="flex-1">
                          <div className="h-3 bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden">
                            <div 
                              className={`h-full ${corCarga} transition-all`} 
                              style={{ width: `${cargaPerc}%` }} 
                            />
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="text-sm font-bold text-slate-900 dark:text-white">{Math.round(cargaPerc)}%</p>
                          <p className="text-xs text-slate-500 dark:text-slate-400">{statusCarga}</p>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Células */}
                  {selectedCell === 'all' && (
                    <div className="border-t border-slate-100 dark:border-white/5 pt-3">
                      <p className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-2">Distribuição por Célula:</p>
                      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2">
                        {getCellasUnicas().map(celula => {
                          const celulasReservas = periodo.reservas.filter(r => {
                            const produto = produtos.find(p => p.letra_produto === r.letra_produto);
                            return produto?.celulas_permitidas?.includes(celula);
                          });

                          if (celulasReservas.length === 0) return null;

                          const unitsCelula = celulasReservas.reduce((sum, r) => sum + (r.quantidade - (r.quantidade_baixada || 0)), 0);

                          return (
                            <div key={celula} className="bg-slate-50 dark:bg-white/5 rounded-lg p-2 border border-transparent dark:border-white/5">
                              <div className="flex items-center gap-1.5 mb-1">
                                <Factory className="w-3.5 h-3.5 text-slate-600 dark:text-slate-400" />
                                <span className="text-xs font-medium text-slate-700 dark:text-slate-300">{celula}</span>
                              </div>
                              <p className="text-xs text-slate-600 dark:text-slate-400">
                                {celulasReservas.length} {celulasReservas.length === 1 ? 'reserva' : 'reservas'} • {unitsCelula.toLocaleString()} un.
                              </p>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            );
          })
        )}
      </div>
    </div>
  );
}

