              ))
            )}
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { rdsn } from '@/api/supabaseClient';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Settings, Plus, Trash2, Edit3, TrendingUp, AlertTriangle } from 'lucide-react';
import { toast } from 'sonner';

export default function KPIConfigurator({ setorId }) {
  const queryClient = useQueryClient();
  const [showDialog, setShowDialog] = useState(false);
  const [editingKPI, setEditingKPI] = useState(null);

  const [formData, setFormData] = useState({
    nome: '',
    descricao: '',
    tipo: 'producao_diaria',
    meta_valor: 0,
    limite_inferior: 0,
    limite_superior: 0,
    notificar_quando_fora_meta: false,
    cor_display: '#3b82f6',
    ativo: true
  });

  const { data: setores = [] } = useQuery({
    queryKey: ['setores'],
    queryFn: () => rdsn.entities.Setor.list()
  });

  const { data: kpis = [] } = useQuery({
    queryKey: ['kpis-config', setorId],
    queryFn: async () => {
      const todosKPIs = await rdsn.entities.ConfiguracaoKPI.list();
      return setorId ? todosKPIs.filter(k => k.setor_id === setorId) : todosKPIs;
    }
  });

  const criarKPIMutation = useMutation({
    mutationFn: (data) => rdsn.entities.ConfiguracaoKPI.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['kpis-config'] });
      setShowDialog(false);
      resetForm();
      toast.success('KPI criado com sucesso!');
    }
  });

  const editarKPIMutation = useMutation({
    mutationFn: ({ id, data }) => rdsn.entities.ConfiguracaoKPI.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['kpis-config'] });
      setShowDialog(false);
      resetForm();
      toast.success('KPI atualizado!');
    }
  });

  const excluirKPIMutation = useMutation({
    mutationFn: (id) => rdsn.entities.ConfiguracaoKPI.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['kpis-config'] });
      toast.success('KPI excluído!');
    }
  });

  const resetForm = () => {
    setFormData({
      nome: '',
      descricao: '',
      tipo: 'producao_diaria',
      meta_valor: 0,
      limite_inferior: 0,
      limite_superior: 0,
      notificar_quando_fora_meta: false,
      cor_display: '#3b82f6',
      ativo: true
    });
    setEditingKPI(null);
  };

  const handleOpenCreate = () => {
    resetForm();
    setShowDialog(true);
  };

  const handleOpenEdit = (kpi) => {
    setEditingKPI(kpi);
    setFormData({
      nome: kpi.nome,
      descricao: kpi.descricao || '',
      tipo: kpi.tipo,
      meta_valor: kpi.meta_valor || 0,
      limite_inferior: kpi.limite_inferior || 0,
      limite_superior: kpi.limite_superior || 0,
      notificar_quando_fora_meta: kpi.notificar_quando_fora_meta || false,
      cor_display: kpi.cor_display || '#3b82f6',
      ativo: kpi.ativo ?? true
    });
    setShowDialog(true);
  };

  const handleSubmit = () => {
    if (!formData.nome) {
      toast.error('Digite um nome para o KPI');
      return;
    }

    const dataToSend = {
      ...formData,
      setor_id: setorId
    };

    if (editingKPI) {
      editarKPIMutation.mutate({ id: editingKPI.id, data: dataToSend });
    } else {
      criarKPIMutation.mutate(dataToSend);
    }
  };

  const tiposKPI = [
    { value: 'producao_diaria', label: 'Produção Diária' },
    { value: 'taxa_eficiencia', label: 'Taxa de Eficiência' },
    { value: 'estoque_disponivel', label: 'Estoque Disponível' },
    { value: 'reservas_ativas', label: 'Reservas Ativas' },
    { value: 'alertas_pendentes', label: 'Alertas Pendentes' },
    { value: 'custom', label: 'Customizado' }
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Settings className="w-5 h-5" />
          Configuração de KPIs
        </h3>
        <Button onClick={handleOpenCreate}>
          <Plus className="w-4 h-4 mr-2" />
          Novo KPI
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {kpis.map(kpi => (
          <Card key={kpi.id} className={!kpi.ativo ? 'opacity-50' : ''}>
            <CardHeader className="pb-3">
              <div className="flex items-start justify-between">
                <div>
                  <CardTitle className="text-base flex items-center gap-2">
                    <div 
                      className="w-3 h-3 rounded-full" 
                      style={{ backgroundColor: kpi.cor_display }}
                    />
                    {kpi.nome}
                  </CardTitle>
                  <p className="text-xs text-slate-500 mt-1">
                    {tiposKPI.find(t => t.value === kpi.tipo)?.label}
                  </p>
                </div>
                <div className="flex gap-1">
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7"
                    onClick={() => handleOpenEdit(kpi)}
                  >
                    <Edit3 className="w-3 h-3" />
                  </Button>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7 text-red-600"
                    onClick={() => excluirKPIMutation.mutate(kpi.id)}
                  >
                    <Trash2 className="w-3 h-3" />
                  </Button>
                </div>
              </div>
            </CardHeader>
            <CardContent className="space-y-2">
              {kpi.meta_valor > 0 && (
                <div className="flex items-center gap-2 text-sm">
                  <TrendingUp className="w-4 h-4 text-green-600" />
                  <span>Meta: {kpi.meta_valor}</span>
                </div>
              )}
              {kpi.notificar_quando_fora_meta && (
                <div className="flex items-center gap-2 text-sm text-amber-600">
                  <AlertTriangle className="w-4 h-4" />
                  <span>Notificações ativas</span>
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>

      {kpis.length === 0 && (
        <Card>
          <CardContent className="text-center py-8">
            <p className="text-slate-500">Nenhum KPI configurado ainda</p>
            <Button onClick={handleOpenCreate} className="mt-4">
              Criar Primeiro KPI
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Dialog de Criação/Edição */}
      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingKPI ? 'Editar KPI' : 'Novo KPI'}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Nome do KPI *</Label>
              <Input
                value={formData.nome}
                onChange={(e) => setFormData(prev => ({ ...prev, nome: e.target.value }))}
                placeholder="Ex: Produção Diária de Lacres"
              />
            </div>

            <div className="space-y-2">
              <Label>Descrição</Label>
              <Input
                value={formData.descricao}
                onChange={(e) => setFormData(prev => ({ ...prev, descricao: e.target.value }))}
                placeholder="Descrição do KPI"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Tipo de KPI</Label>
                <Select 
                  value={formData.tipo} 
                  onValueChange={(v) => setFormData(prev => ({ ...prev, tipo: v }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {tiposKPI.map(tipo => (
                      <SelectItem key={tipo.value} value={tipo.value}>
                        {tipo.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Cor de Exibição</Label>
                <Input
                  type="color"
                  value={formData.cor_display}
                  onChange={(e) => setFormData(prev => ({ ...prev, cor_display: e.target.value }))}
                />
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label>Meta</Label>
                <Input
                  type="number"
                  value={formData.meta_valor}
                  onChange={(e) => setFormData(prev => ({ ...prev, meta_valor: parseFloat(e.target.value) || 0 }))}
                />
              </div>

              <div className="space-y-2">
                <Label>Limite Inferior</Label>
                <Input
                  type="number"
                  value={formData.limite_inferior}
                  onChange={(e) => setFormData(prev => ({ ...prev, limite_inferior: parseFloat(e.target.value) || 0 }))}
                />
              </div>

              <div className="space-y-2">
                <Label>Limite Superior</Label>
                <Input
                  type="number"
                  value={formData.limite_superior}
                  onChange={(e) => setFormData(prev => ({ ...prev, limite_superior: parseFloat(e.target.value) || 0 }))}
                />
              </div>
            </div>

            <div className="flex items-center justify-between border rounded-lg p-3">
              <div>
                <Label>Notificar quando fora da meta</Label>
                <p className="text-xs text-slate-500">Enviar alertas automáticos</p>
              </div>
              <Switch
                checked={formData.notificar_quando_fora_meta}
                onCheckedChange={(v) => setFormData(prev => ({ ...prev, notificar_quando_fora_meta: v }))}
              />
            </div>

            <div className="flex items-center justify-between border rounded-lg p-3">
              <Label>KPI Ativo</Label>
              <Switch
                checked={formData.ativo}
                onCheckedChange={(v) => setFormData(prev => ({ ...prev, ativo: v }))}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowDialog(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSubmit}>
              {editingKPI ? 'Salvar Alterações' : 'Criar KPI'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { TrendingUp, TrendingDown, AlertCircle, Save, 
  Pencil, X, Clock 
} from 'lucide-react';
import { toast } from "sonner";

function MovimentacaoItem({ mov }) {
  const isEntrada = mov.tipo === 'ENTRADA' || mov.tipo === 'PRODUCAO';
  return (
    <div className="flex items-center justify-between py-2.5 border-b border-slate-100 last:border-0">
      <div className="flex items-center gap-2.5">
        <div className={`p-1.5 rounded-md ${isEntrada ? 'bg-green-100' : 'bg-red-100'}`}>
          {isEntrada 
            ? <TrendingUp className="w-3.5 h-3.5 text-green-600" /> 
            : <TrendingDown className="w-3.5 h-3.5 text-red-600" />}
        </div>
        <div>
          <div className="text-sm font-medium text-slate-800">{mov.tipo}</div>
          <div className="text-xs text-slate-500">
            {new Date(mov.created_at).toLocaleString('pt-BR')}
          </div>
        </div>
      </div>
      <div className="text-right">
        <div className={`text-sm font-bold ${isEntrada ? 'text-green-600' : 'text-red-600'}`}>
          {isEntrada ? '+' : '-'}{mov.quantidade}
        </div>
        <div className="text-xs text-slate-400">{mov.quantidade_anterior} → {mov.quantidade_nova}</div>
      </div>
    </div>
  );
}

export default function ProdutoDetalheModal({ produto, open, onOpenChange }) {
  const queryClient = useQueryClient();
  const [editMode, setEditMode] = useState(false);
  const [editData, setEditData] = useState({});

  const { data: movimentacoes = [], isLoading: loadingMov } = useQuery({
    queryKey: ['mov-produto', produto?.id],
    queryFn: async () => {
      const todas = await rdsn.entities.MovimentacaoEstoque.list('-created_at', 100);
      return todas.filter(m => m.produto_id === produto.id);
    },
    enabled: !!produto?.id && open
  });

  const { data: alertas = [], isLoading: loadingAlertas } = useQuery({
    queryKey: ['alertas-produto', produto?.id],
    queryFn: async () => {
      return await rdsn.entities.Alerta.filter({ 
        entidade_id: produto.id, 
        resolvido: false 
      });
    },
    enabled: !!produto?.id && open
  });

  const { data: setor } = useQuery({
    queryKey: ['setor-produto', produto?.setor_id],
    queryFn: () => rdsn.entities.Setor.filter({ id: produto.setor_id }),
    enabled: !!produto?.setor_id && open,
    select: (data) => data?.[0] || null
  });

  const updateMutation = useMutation({
    mutationFn: (data) => rdsn.entities.Produto.update(produto.id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      toast.success('Produto atualizado');
      setEditMode(false);
    },
    onError: (e) => toast.error('Erro: ' + e.message)
  });

  const startEdit = () => {
    setEditData({
      estoque_atual: produto.estoque_atual || 0,
      estoque_minimo: produto.estoque_minimo || 0,
      descricao: produto.descricao || '',
      codigo_produto: produto.codigo_produto || ''
    });
    setEditMode(true);
  };

  const handleSave = () => {
    updateMutation.mutate({
      estoque_atual: Number(editData.estoque_atual),
      estoque_minimo: Number(editData.estoque_minimo),
      descricao: editData.descricao,
      codigo_produto: editData.codigo_produto
    });
  };

  if (!produto) return null;

  const baixo = (produto.estoque_atual || 0) < (produto.estoque_minimo || 0) && (produto.estoque_minimo || 0) > 0;

  // Calcular estatísticas das movimentações
  const ultimos30dias = movimentacoes.filter(m => {
    const diff = Date.now() - new Date(m.created_at).getTime();
    return diff < 30 * 24 * 60 * 60 * 1000;
  });
  const entradas30d = ultimos30dias.filter(m => m.tipo === 'ENTRADA' || m.tipo === 'PRODUCAO').reduce((s, m) => s + (m.quantidade || 0), 0);
  const saidas30d = ultimos30dias.filter(m => m.tipo === 'SAIDA' || m.tipo === 'BAIXA').reduce((s, m) => s + (m.quantidade || 0), 0);

  return (
    <Dialog open={open} onOpenChange={(v) => { onOpenChange(v); if (!v) setEditMode(false); }}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3">
            <div className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold text-lg ${
              baixo ? 'bg-red-100 text-red-700' : 'bg-slate-900 text-white'
            }`}>
              {produto.letra_produto}
            </div>
            <div>
              <div className="text-xl">{produto.letra_produto}{produto.sufixo}</div>
              <div className="text-sm font-normal text-slate-500">{produto.descricao || produto.modelo || ''}</div>
            </div>
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-5 mt-2">
          {/* Alertas ativos */}
          {alertas.length > 0 && (
            <div className="space-y-2">
              {alertas.map(a => (
                <div key={a.id} className="bg-red-50 border border-red-200 rounded-lg p-3 flex items-start gap-2">
                  <AlertCircle className="w-4 h-4 text-red-500 mt-0.5 shrink-0" />
                  <div>
                    <div className="text-sm font-medium text-red-800">{a.titulo}</div>
                    <div className="text-xs text-red-600">{a.descricao}</div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Informações e edição rápida */}
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-slate-800 text-sm">Informações do Produto</h3>
                {!editMode ? (
                  <Button variant="ghost" size="sm" onClick={startEdit} className="h-7 text-xs">
                    <Pencil className="w-3 h-3 mr-1" /> Editar
                  </Button>
                ) : (
                  <div className="flex gap-1">
                    <Button variant="ghost" size="sm" onClick={() => setEditMode(false)} className="h-7 text-xs">
                      <X className="w-3 h-3 mr-1" /> Cancelar
                    </Button>
                    <Button size="sm" onClick={handleSave} disabled={updateMutation.isPending} className="h-7 text-xs">
                      <Save className="w-3 h-3 mr-1" /> Salvar
                    </Button>
                  </div>
                )}
              </div>

              {editMode ? (
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-xs">Estoque Atual</Label>
                    <Input type="number" value={editData.estoque_atual}
                      onChange={e => setEditData({...editData, estoque_atual: e.target.value})} />
                  </div>
                  <div>
                    <Label className="text-xs">Estoque Mínimo</Label>
                    <Input type="number" value={editData.estoque_minimo}
                      onChange={e => setEditData({...editData, estoque_minimo: e.target.value})} />
                  </div>
                  <div>
                    <Label className="text-xs">Descrição</Label>
                    <Input value={editData.descricao}
                      onChange={e => setEditData({...editData, descricao: e.target.value})} />
                  </div>
                  <div>
                    <Label className="text-xs">Código Técnico</Label>
                    <Input value={editData.codigo_produto}
                      onChange={e => setEditData({...editData, codigo_produto: e.target.value})} />
                  </div>
                </div>
              ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  <InfoBlock label="Estoque Atual" value={(produto.estoque_atual || 0).toLocaleString()} 
                    highlight={baixo ? 'red' : null} />
                  <InfoBlock label="Estoque Mínimo" value={(produto.estoque_minimo || 0).toLocaleString()} />
                  <InfoBlock label="Categoria" value={produto.categoria || 'N/A'} />
                  <InfoBlock label="Código Técnico" value={produto.codigo_produto || 'N/A'} />
                  <InfoBlock label="Modelo" value={produto.modelo || 'N/A'} />
                  <InfoBlock label="Setor" value={setor?.nome || 'N/A'} />
                  <InfoBlock label="Prefixo" value={produto.prefixo_padrao || 'N/A'} />
                  <InfoBlock label="Status" value={produto.ativo ? 'Ativo' : 'Inativo'} 
                    highlight={produto.ativo ? 'green' : 'gray'} />
                </div>
              )}
            </CardContent>
          </Card>

          {/* KPIs de movimentação 30 dias */}
          <div className="grid grid-cols-3 gap-3">
            <Card>
              <CardContent className="p-3 text-center">
                <div className="text-xs text-slate-500 mb-1">Movimentações (30d)</div>
                <div className="text-xl font-bold text-slate-900">{ultimos30dias.length}</div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-3 text-center">
                <div className="text-xs text-slate-500 mb-1">Entradas (30d)</div>
                <div className="text-xl font-bold text-green-600">+{entradas30d.toLocaleString()}</div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-3 text-center">
                <div className="text-xs text-slate-500 mb-1">Saídas (30d)</div>
                <div className="text-xl font-bold text-red-600">-{saidas30d.toLocaleString()}</div>
              </CardContent>
            </Card>
          </div>

          {/* Histórico de Movimentações */}
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center gap-2 mb-3">
                <Clock className="w-4 h-4 text-slate-500" />
                <h3 className="font-semibold text-slate-800 text-sm">Histórico de Movimentações</h3>
                <Badge variant="secondary" className="ml-auto text-xs">{movimentacoes.length}</Badge>
              </div>
              {loadingMov ? (
                <div className="text-center py-4 text-sm text-slate-500">Carregando...</div>
              ) : movimentacoes.length === 0 ? (
                <div className="text-center py-6 text-sm text-slate-400">
                  Nenhuma movimentação registrada
                </div>
              ) : (
                <div className="max-h-64 overflow-y-auto">
                  {movimentacoes.slice(0, 20).map(mov => (
                    <MovimentacaoItem key={mov.id} mov={mov} />
                  ))}
                  {movimentacoes.length > 20 && (
                    <div className="text-center py-2 text-xs text-slate-400">
                      +{movimentacoes.length - 20} movimentações anteriores
                    </div>
                  )}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function InfoBlock({ label, value, highlight }) {
  const colorMap = {
    red: 'text-red-600 font-bold',
    green: 'text-green-600 font-medium',
    gray: 'text-slate-400'
  };
  return (
    <div className="bg-slate-50 rounded-lg p-2.5">
      <div className="text-xs text-slate-500 mb-0.5">{label}</div>
      <div className={`text-sm font-medium ${highlight ? colorMap[highlight] : 'text-slate-900'}`}>
        {value}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useNotifications } from '@/components/hooks/useNotifications';
import { Bell, Check, Trash2, AlertCircle, Info, CheckCircle, XCircle, ExternalLink, Clock } from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { ScrollArea } from "@/components/ui/scroll-area";
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';

const tipoIconMap = {
  INFO: { icon: Info, color: 'text-blue-600', bg: 'bg-blue-50', border: 'border-blue-200' },
  ALERTA: { icon: AlertCircle, color: 'text-amber-600', bg: 'bg-amber-50', border: 'border-amber-200' },
  ERRO: { icon: XCircle, color: 'text-red-600', bg: 'bg-red-50', border: 'border-red-200' },
  SUCESSO: { icon: CheckCircle, color: 'text-green-600', bg: 'bg-green-50', border: 'border-green-200' }
};

const prioridadeConfig = {
  CRITICA: { label: 'Crítica', color: 'bg-red-600', pulse: true },
  ALTA: { label: 'Alta', color: 'bg-orange-500', pulse: false },
  MEDIA: { label: 'Média', color: 'bg-blue-500', pulse: false },
  BAIXA: { label: 'Baixa', color: 'bg-slate-400', pulse: false },
};

export default function NotificationCenter({ userId }) {
  const [open, setOpen] = useState(false);
  const {
    notificacoes,
    naoLidas,
    isLoading,
    marcarComoLida,
    arquivar,
    marcarTodasComoLidas,
  } = useNotifications(userId);

  const unreadCount = naoLidas.length;

  // Agrupar notificações por lida/não lida
  const notificacoesAgrupadas = notificacoes.reduce((acc, notif) => {
    const grupo = notif.lida ? 'lidas' : 'naoLidas';
    if (!acc[grupo]) acc[grupo] = [];
    acc[grupo].push(notif);
    return acc;
  }, { naoLidas: [], lidas: [] });

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <motion.button 
          className="relative p-2 hover:bg-slate-100 rounded-lg transition-colors"
          aria-label={`Notificações. ${unreadCount > 0 ? `${unreadCount} não lidas` : 'Nenhuma não lida'}`}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          <Bell className={cn(
            "w-5 h-5 transition-colors",
            unreadCount > 0 ? "text-blue-600" : "text-slate-600"
          )} aria-hidden="true" />
          <AnimatePresence>
            {unreadCount > 0 && (
              <motion.span
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                exit={{ scale: 0 }}
                className="absolute -top-1 -right-1 w-5 h-5 bg-gradient-to-br from-red-500 to-red-600 text-white text-xs font-bold rounded-full flex items-center justify-center shadow-lg"
              >
                {unreadCount > 9 ? '9+' : unreadCount}
              </motion.span>
            )}
          </AnimatePresence>
        </motion.button>
      </PopoverTrigger>

      <PopoverContent className="w-[420px] p-0 shadow-xl" align="end">
        <div className="p-4 border-b border-slate-200 bg-gradient-to-r from-slate-50 to-slate-100">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-blue-600 rounded-lg flex items-center justify-center">
                <Bell className="w-4 h-4 text-white" />
              </div>
              <div>
                <h3 className="font-semibold text-slate-900">Notificações</h3>
                {unreadCount > 0 && (
                  <p className="text-xs text-slate-600">{unreadCount} não lida{unreadCount > 1 ? 's' : ''}</p>
                )}
              </div>
            </div>
            {naoLidas.length > 0 && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => marcarTodasComoLidas()}
                className="text-xs hover:bg-white"
              >
                <Check className="w-3 h-3 mr-1" />
                Marcar todas
              </Button>
            )}
          </div>
        </div>

        <ScrollArea className="h-[500px]">
          {notificacoes.length === 0 ? (
            <div className="p-12 text-center text-slate-500">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-3">
                <Bell className="w-8 h-8 opacity-30" />
              </div>
              <p className="font-medium">Nenhuma notificação</p>
              <p className="text-xs mt-1">Você está em dia!</p>
            </div>
          ) : (
            <>
              {/* Notificações Não Lidas */}
              {notificacoesAgrupadas.naoLidas.length > 0 && (
                <div>
                  <div className="px-4 py-2 bg-blue-50 border-b border-blue-100">
                    <p className="text-xs font-semibold text-blue-900 uppercase tracking-wide">
                      Não Lidas ({notificacoesAgrupadas.naoLidas.length})
                    </p>
                  </div>
                  <AnimatePresence>
                    {notificacoesAgrupadas.naoLidas.map((notif) => (
                      <NotificationItem
                        key={notif.id}
                        notif={notif}
                        marcarComoLida={marcarComoLida}
                        arquivar={arquivar}
                        setOpen={setOpen}
                      />
                    ))}
                  </AnimatePresence>
                </div>
              )}

              {/* Notificações Lidas */}
              {notificacoesAgrupadas.lidas.length > 0 && (
                <div>
                  <div className="px-4 py-2 bg-slate-50 border-b border-slate-100">
                    <p className="text-xs font-semibold text-slate-600 uppercase tracking-wide">
                      Lidas ({notificacoesAgrupadas.lidas.length})
                    </p>
                  </div>
                  {notificacoesAgrupadas.lidas.map((notif) => (
                    <NotificationItem
                      key={notif.id}
                      notif={notif}
                      marcarComoLida={marcarComoLida}
                      arquivar={arquivar}
                      setOpen={setOpen}
                      isRead
                    />
                  ))}
                </div>
              )}
            </>
          )}
        </ScrollArea>
      </PopoverContent>
    </Popover>
  );
}

// Componente de Item de Notificação
function NotificationItem({ notif, marcarComoLida, arquivar, setOpen, isRead = false }) {
  const { icon: Icon, color, bg, border } = tipoIconMap[notif.tipo] || tipoIconMap.INFO;
  const prioridadeInfo = prioridadeConfig[notif.prioridade] || prioridadeConfig.MEDIA;

  return (
    <motion.div
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 20 }}
      className={cn(
        "p-4 border-b border-slate-100 hover:bg-slate-50 transition-all",
        !isRead && "bg-blue-50/30"
      )}
    >
      <div className="flex gap-3">
        <div className={cn(
          "flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center mt-1",
          bg, border, "border"
        )}>
          <Icon className={cn("w-5 h-5", color)} />
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2 mb-1">
            <h4 className={cn(
              "text-sm text-slate-900",
              !isRead ? "font-semibold" : "font-medium"
            )}>
              {notif.titulo}
            </h4>
            {notif.prioridade && notif.prioridade !== 'BAIXA' && (
              <Badge 
                className={cn(
                  "text-xs px-2 py-0 text-white",
                  prioridadeInfo.color,
                  prioridadeInfo.pulse && "animate-pulse"
                )}
              >
                {prioridadeInfo.label}
              </Badge>
            )}
          </div>

          <p className="text-sm text-slate-600 mb-2 line-clamp-2">{notif.mensagem}</p>

          <div className="flex items-center justify-between gap-2 flex-wrap">
            <span className="text-xs text-slate-500 flex items-center gap-1">
              <Clock className="w-3 h-3" />
              {format(new Date(notif.created_at), "dd/MM 'às' HH:mm", { locale: ptBR })}
            </span>

            <div className="flex items-center gap-1">
              {notif.link_relacionado && (
                <Link
                  to={notif.link_relacionado}
                  onClick={() => {
                    setOpen(false);
                    if (!isRead) marcarComoLida(notif.id);
                  }}
                >
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 text-xs hover:bg-blue-100"
                  >
                    <ExternalLink className="w-3 h-3 mr-1" />
                    Abrir
                  </Button>
                </Link>
              )}

              {!isRead && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={(e) => {
                    e.stopPropagation();
                    marcarComoLida(notif.id);
                  }}
                  className="h-7 text-xs hover:bg-green-100"
                  title="Marcar como lida"
                >
                  <Check className="w-3 h-3" />
                </Button>
              )}

              <Button
                variant="ghost"
                size="sm"
                onClick={(e) => {
                  e.stopPropagation();
                  arquivar(notif.id);
                }}
                className="h-7 text-xs hover:bg-red-100 text-slate-600"
                title="Arquivar notificação"
              >
                <Trash2 className="w-3 h-3" />
              </Button>
            </div>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

import React from 'react';
import { useSetor } from '@/components/context/SetorContext';
import { useQuery } from '@tanstack/react-query';
import { rdsn } from '@/api/supabaseClient';
import { AlertTriangle, Factory } from 'lucide-react';

/**
 * Guard que bloqueia acesso/registro PCP se nenhum setor específico estiver selecionado.
 * Usado em páginas e modais do módulo PCP.
 * 
 * @param {string} [action] - Descrição da ação bloqueada (ex: "criar nova OP")
 * @param {boolean} [inline] - Se true, renderiza como banner em vez de bloquear tela inteira
 * @param {React.ReactNode} children - Conteúdo a renderizar quando desbloqueado
 */
export default function PCPSetorGuard({ children, action = 'realizar esta ação', inline = false }) {
  const { setorAtivo, isAdmin } = useSetor();

  const { data: setores = [] } = useQuery({
    queryKey: ['setores-all'],
    queryFn: () => rdsn.entities.Setor.list('nome', 200),
    staleTime: 60000,
  });
  const setor = setores.find(s => s.id === setorAtivo) || null;

  const bloqueado = !setorAtivo || setorAtivo === 'ALL';

  if (!bloqueado) return children;

  const nomeSetor = setor?.nome || setorAtivo;

  if (inline) {
    return (
      <div className="rounded-lg border border-amber-300 bg-amber-50 px-4 py-3 flex items-start gap-3 text-sm text-amber-800 mb-4">
        <AlertTriangle className="w-5 h-5 flex-shrink-0 mt-0.5 text-amber-500" />
        <div>
          <strong>Setor não selecionado.</strong> Para {action}, selecione um setor específico no seletor de setor no topo da página.
          Registros PCP são isolados por setor.
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] p-8 text-center">
      <div className="w-20 h-20 rounded-full bg-amber-100 flex items-center justify-center mb-6">
        <Factory className="w-10 h-10 text-amber-500" />
      </div>
      <h2 className="text-xl font-bold text-slate-800 mb-2">Setor não selecionado</h2>
      <p className="text-slate-500 max-w-sm mb-4">
        Para {action}, selecione um <strong>setor específico</strong> no seletor de setor no topo da página.
      </p>
      <div className="px-4 py-2 bg-amber-100 border border-amber-300 rounded-lg text-amber-800 text-sm font-medium">
        ⚠ Os dados PCP são isolados por setor. Selecione seu setor para continuar.
      </div>
    </div>
  );
}

/**
 * Hook para obter o setor ativo com nome, para exibir em formulários
 */
export function usePCPSetor() {
  const { setorAtivo, isAdmin } = useSetor();
  const bloqueado = !setorAtivo || setorAtivo === 'ALL';

  const { data: setores = [] } = useQuery({
    queryKey: ['setores-all'],
    queryFn: () => rdsn.entities.Setor.list('nome', 200),
    staleTime: 60000,
  });

  const setor = setores.find(s => s.id === setorAtivo) || null;

  return { setorAtivo, bloqueado, setor, nomeSetor: setor?.nome || (bloqueado ? 'Todos os Setores' : setorAtivo) };
}

