                      <TableCell>
                        <Badge variant={reserva.status === 'PRODUZIDO' ? 'default' : 'outline'}>
                          {reserva.status}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
