            <PaginacaoTabela
              totalItems={dadosFiltrados.length}
              paginaAtual={paginaAtual}
              itensPorPagina={itensPorPagina}
              onPaginaChange={setPaginaAtual}
              onItensPorPaginaChange={(v) => { setItensPorPagina(v); setPaginaAtual(1); }}
            />
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

